// Plus Two entrance chemistry bank: Some basic concepts (mole concept and stoichiometry). Original fibub questions.
// Atomic masses used: H 1, C 12, N 14, O 16, Na 23, Mg 24, Al 27, S 32, Cl 35.5, K 39, Ca 40, Fe 56, Cu 63.5. N_A = 6.022 × 10^23.
import { pick, int, choose, fmt, shuffleOpts, numOpts } from '../_entrance.js';

let _n = 0;
const EX = { 1: ['keam', 'cusat', 'comedk', 'jee-main', 'neet'], 2: ['keam', 'cusat', 'comedk', 'jee-main', 'neet'], 3: ['jee-main', 'neet', 'comedk'], 4: ['jee-main', 'jee-adv', 'neet'], 5: ['jee-adv'] };
const A4 = ['Both A and R are true and R is the correct explanation of A', 'Both A and R are true but R is not the correct explanation of A', 'A is true but R is false', 'A is false but R is true'];
const S4 = ['Both Statement I and Statement II are correct', 'Statement I is correct but Statement II is incorrect', 'Statement I is incorrect but Statement II is correct', 'Both Statement I and Statement II are incorrect'];
/** single-answer mcq; the correct option goes to a rotating position so answers spread evenly */
const mk = (id, level, sub, q, right, wrongs, sol, trap) => {
  const pos = (_n++) % 4; const options = [...wrongs]; options.splice(pos, 0, right);
  return { id, type: 'mcq', level, format: 'single', exams: EX[level], sub, q, options, answer: pos, sol, ...(trap ? { trap } : {}) };
};
const nat = (id, level, sub, q, answer, tol, unit, sol, trap) => ({ id, type: 'nat', level, format: tol === 0 ? 'integer' : 'numeric', exams: EX[level], sub, q, answer, tol, ...(unit ? { unit } : {}), sol, ...(trap ? { trap } : {}) });
const msq = (id, level, sub, q, options, answer, sol, trap) => ({ id, type: 'msq', level, format: 'multi', exams: level >= 4 ? ['jee-adv'] : ['jee-adv', 'jee-main'], sub, q, options, answer, sol, ...(trap ? { trap } : {}) });
const asr = (id, level, sub, A, R, answer, sol, trap) => ({ id, type: 'mcq', level, format: 'assertion', exams: EX[level], sub, q: `<p><b>Assertion (A):</b> ${A}</p><p><b>Reason (R):</b> ${R}</p>`, options: A4, answer, sol, ...(trap ? { trap } : {}) });
const stm = (id, level, sub, s1, s2, answer, sol, trap) => ({ id, type: 'mcq', level, format: 'statements', exams: EX[level], sub, q: `<p><b>Statement I:</b> ${s1}</p><p><b>Statement II:</b> ${s2}</p>`, options: S4, answer, sol, ...(trap ? { trap } : {}) });
const mat = (id, level, sub, group, q, right, wrongs, sol, trap) => ({ ...mk(id, level, sub, q, right, wrongs, sol, trap), format: 'match', group });
const P = (id, level, sub, group, q, right, wrongs, sol, trap) => ({ ...mk(id, level, sub, q, right, wrongs, sol, trap), format: 'passage', group });
const PN = (id, level, sub, group, q, answer, tol, unit, sol, trap) => ({ ...nat(id, level, sub, q, answer, tol, unit, sol, trap), format: 'passage', group });

export default {
  topic: 'mole-concept',
  groups: {
    m1: { title: 'Match the sample with its mass', list1: ['A. 0.25 mol of CH<sub>4</sub>', 'B. 11.2 L of N<sub>2</sub> at 273 K and 1 atm', 'C. 3.011 × 10<sup>23</sup> molecules of H<sub>2</sub>O', 'D. 0.1 mol of CaCO<sub>3</sub>'], list2: ['p. 9 g', 'q. 4 g', 'r. 10 g', 's. 14 g'] },
    m2: { title: 'Match the law with its example', list1: ['A. Law of definite proportions', 'B. Law of multiple proportions', 'C. Gay-Lussac law of gaseous volumes', 'D. Law of conservation of mass'], list2: ['p. CO and CO<sub>2</sub>: for a fixed 12 g of carbon, oxygen is 16 g and 32 g', 'q. Water from a river, a tap or a lab always has H : O = 1 : 8 by mass', 'r. 2 volumes of H<sub>2</sub> and 1 volume of O<sub>2</sub> give 2 volumes of steam', 's. A candle burnt in a sealed jar: total mass before and after is the same'] },
    m3: { title: 'Match the change with the n-factor', list1: ['A. KMnO<sub>4</sub> to Mn<sup>2+</sup> (acidic medium)', 'B. KMnO<sub>4</sub> to MnO<sub>2</sub> (neutral medium)', 'C. K<sub>2</sub>Cr<sub>2</sub>O<sub>7</sub> to Cr<sup>3+</sup> (per formula unit)', 'D. H<sub>2</sub>C<sub>2</sub>O<sub>4</sub> to CO<sub>2</sub>'], list2: ['p. 2', 'q. 3', 'r. 5', 's. 6'] },
    p1: { title: 'Combustion analysis', passage: '<p>A student burns <b>0.92 g</b> of a compound that contains only C, H and O in excess oxygen. She collects <b>1.76 g</b> of CO<sub>2</sub> and <b>1.08 g</b> of H<sub>2</sub>O. The vapour density of the compound is 23.</p>' },
    p2: { title: 'A water-ethanol solution', passage: '<p>A solution of ethanol (C<sub>2</sub>H<sub>5</sub>OH, M = 46 g mol<sup>-1</sup>) in water is <b>23% ethanol by mass</b>. Its density is <b>0.96 g mL<sup>-1</sup></b>. Take water as 18 g mol<sup>-1</sup>.</p>' },
    p3: { title: 'A mixture of carbonates', passage: '<p>A 0.486 g mixture of Na<sub>2</sub>CO<sub>3</sub> and NaHCO<sub>3</sub> is dissolved in water and titrated with 0.100 M HCl. With phenolphthalein, the colour goes at <b>30.0 mL</b>. Adding methyl orange and continuing, the second end point is reached at a total of <b>80.0 mL</b>. (Phenolphthalein: Na<sub>2</sub>CO<sub>3</sub> + HCl gives NaHCO<sub>3</sub> + NaCl. Methyl orange: all carbonate and bicarbonate become CO<sub>2</sub>.)</p>' },
  },
  items: [
    // ---------- Level 1 ----------
    mk('mc-001', 1, 'mole and molar mass', 'What is the mass of 2 mol of water, H<sub>2</sub>O?', '36 g', ['18 g', '72 g', '9 g'], '<p>Idea: mass = moles × molar mass.</p><p>Molar mass of H<sub>2</sub>O = 2(1) + 16 = 18 g mol<sup>-1</sup>.</p><p>Mass = 2 × 18 = <b>36 g</b>.</p><p>18 g is the mass of 1 mol (you forgot to multiply by 2). 72 g multiplies by 4 by mistake.</p>'),
    mk('mc-002', 1, 'Avogadro number', 'How many molecules are present in 0.5 mol of any molecular substance?', '3.011 × 10<sup>23</sup>', ['6.022 × 10<sup>23</sup>', '1.2044 × 10<sup>24</sup>', '3.011 × 10<sup>22</sup>'], '<p>Idea: 1 mol has N<sub>A</sub> = 6.022 × 10<sup>23</sup> particles.</p><p>0.5 × 6.022 × 10<sup>23</sup> = <b>3.011 × 10<sup>23</sup></b> molecules.</p>'),
    mk('mc-003', 1, 'molar mass', 'The molar mass of calcium carbonate, CaCO<sub>3</sub>, is', '100 g mol<sup>-1</sup>', ['84 g mol<sup>-1</sup>', '68 g mol<sup>-1</sup>', '116 g mol<sup>-1</sup>'], '<p>Add the atomic masses: Ca 40 + C 12 + 3 × O (3 × 16 = 48) = <b>100</b> g mol<sup>-1</sup>.</p><p>84 would be MgCO<sub>3</sub> (24 + 12 + 48). 68 forgets that there are three oxygens.</p>'),
    mk('mc-004', 1, 'laws of chemical combination', 'Pure water from a well and pure water made by burning hydrogen in oxygen both have hydrogen and oxygen in the mass ratio 1 : 8. This illustrates the law of', 'definite proportions', ['multiple proportions', 'reciprocal proportions', 'conservation of mass'], '<p>The same compound always has the same elements in the same fixed mass ratio, whatever its source. That is the law of <b>definite proportions</b> (Proust).</p><p>Multiple proportions needs two different compounds of the same elements. Conservation of mass is about total mass in a change.</p>'),
    mk('mc-005', 1, 'percentage composition', 'What is the mass percentage of oxygen in water (H<sub>2</sub>O)? (H = 1, O = 16)', '88.9%', ['11.1%', '94.1%', '50%'], '<p>Mass % = (mass of element in one formula unit / molar mass) × 100.</p><p>= (16 / 18) × 100 = <b>88.9%</b>. The 11.1% is hydrogen.</p>'),
    mk('mc-006', 1, 'atoms in a mole', 'How many atoms are present in 1 mol of CO<sub>2</sub>?', '3 N<sub>A</sub>', ['N<sub>A</sub>', '2 N<sub>A</sub>', '44 N<sub>A</sub>'], '<p>1 mol of CO<sub>2</sub> has N<sub>A</sub> molecules. Each molecule has 1 C + 2 O = 3 atoms.</p><p>Total atoms = <b>3 N<sub>A</sub></b>. N<sub>A</sub> counts molecules, not atoms.</p>'),
    mk('mc-007', 1, 'empirical formula', 'The empirical formula of glucose, C<sub>6</sub>H<sub>12</sub>O<sub>6</sub>, is', 'CH<sub>2</sub>O', ['C<sub>3</sub>H<sub>6</sub>O<sub>3</sub>', 'CHO', 'C<sub>2</sub>H<sub>4</sub>O<sub>2</sub>'], '<p>The empirical formula is the simplest whole-number ratio. C : H : O = 6 : 12 : 6. Divide by 6 to get 1 : 2 : 1.</p><p>So the empirical formula is <b>CH<sub>2</sub>O</b>. The others are not in the lowest ratio.</p>'),
    mk('mc-008', 1, 'molarity', 'A solution has 4 g of NaOH dissolved to make 500 mL of solution. Its molarity is (Na = 23, O = 16, H = 1)', '0.2 M', ['0.1 M', '0.4 M', '0.02 M'], '<p>Moles of NaOH = 4 / 40 = 0.1 mol.</p><p>Volume = 0.5 L, so M = 0.1 / 0.5 = <b>0.2 M</b>.</p><p>0.1 M forgets to convert 500 mL to 0.5 L.</p>', 'Always convert mL to litres before dividing.'),
    mk('mc-009', 1, 'laws of chemical combination', 'Carbon forms two oxides, CO and CO<sub>2</sub>. For the same 12 g of carbon, the masses of oxygen are 16 g and 32 g. The ratio 1 : 2 shows the law of', 'multiple proportions', ['definite proportions', 'conservation of mass', 'Avogadro\'s law'], '<p>Two compounds of the same two elements. For a fixed mass of one element, the masses of the other are in a simple whole-number ratio (16 : 32 = 1 : 2).</p><p>That is the law of <b>multiple proportions</b> (Dalton).</p>'),
    mk('mc-010', 1, 'molar volume', 'What volume does 0.5 mol of an ideal gas occupy at 273 K and 1 atm?', '11.2 L', ['22.4 L', '5.6 L', '44.8 L'], '<p>One mole of an ideal gas at 273 K and 1 atm occupies 22.4 L.</p><p>0.5 mol occupies 0.5 × 22.4 = <b>11.2 L</b>.</p>'),
    nat('mc-011', 1, 'mole and molar mass', 'How many moles are present in 88 g of CO<sub>2</sub>? (C = 12, O = 16)', 2, 0, 'mol', '<p>Molar mass of CO<sub>2</sub> = 12 + 32 = 44 g mol<sup>-1</sup>.</p><p>Moles = 88 / 44 = <b>2</b>.</p>'),
    // ---------- Level 2 ----------
    mk('mc-012', 2, 'mole and molar mass', 'What is the mass of one molecule of water in grams? (N<sub>A</sub> = 6.022 × 10<sup>23</sup>)', '2.99 × 10<sup>-23</sup> g', ['18 g', '1.08 × 10<sup>25</sup> g', '3.34 × 10<sup>22</sup> g'], '<p>Idea: mass of one molecule = molar mass / N<sub>A</sub>.</p><p>18 / 6.022 × 10<sup>23</sup> = <b>2.99 × 10<sup>-23</sup> g</b>.</p><p>3.34 × 10<sup>22</sup> is the number of molecules in 1 g (inverted).</p>'),
    nat('mc-013', 2, 'percentage composition', 'What mass of iron is present in 160 g of Fe<sub>2</sub>O<sub>3</sub>? (Fe = 56, O = 16)', 112, 0, 'g', '<p>Molar mass of Fe<sub>2</sub>O<sub>3</sub> = 2(56) + 3(16) = 112 + 48 = 160 g mol<sup>-1</sup>.</p><p>So 160 g is exactly 1 mol, and it has 2 mol Fe = 2 × 56 = <b>112 g</b>.</p>'),
    mk('mc-014', 2, 'empirical formula', 'A compound has 40.0% C, 6.7% H and 53.3% O by mass. Its empirical formula is (C = 12, H = 1, O = 16)', 'CH<sub>2</sub>O', ['C<sub>2</sub>H<sub>4</sub>O', 'CHO', 'C<sub>2</sub>H<sub>2</sub>O'], '<p>Take 100 g. Moles: C 40/12 = 3.33; H 6.7/1 = 6.7; O 53.3/16 = 3.33.</p><p>Divide by the smallest (3.33): C : H : O = 1 : 2 : 1.</p><p>Empirical formula = <b>CH<sub>2</sub>O</b>.</p>'),
    mk('mc-015', 2, 'molecular formula', 'The empirical formula of a compound is CH<sub>2</sub>O and its molar mass is 180 g mol<sup>-1</sup>. Its molecular formula is', 'C<sub>6</sub>H<sub>12</sub>O<sub>6</sub>', ['C<sub>3</sub>H<sub>6</sub>O<sub>3</sub>', 'C<sub>12</sub>H<sub>24</sub>O<sub>12</sub>', 'C<sub>5</sub>H<sub>10</sub>O<sub>5</sub>'], '<p>Empirical formula mass of CH<sub>2</sub>O = 12 + 2 + 16 = 30.</p><p>n = 180 / 30 = 6. Molecular formula = (CH<sub>2</sub>O)<sub>6</sub> = <b>C<sub>6</sub>H<sub>12</sub>O<sub>6</sub></b>.</p>'),
    mk('mc-016', 2, 'stoichiometry', 'In N<sub>2</sub> + 3H<sub>2</sub> → 2NH<sub>3</sub>, how many grams of NH<sub>3</sub> form from 14 g of N<sub>2</sub> with excess H<sub>2</sub>? (N = 14, H = 1)', '17 g', ['34 g', '8.5 g', '28 g'], '<p>14 g of N<sub>2</sub> is 14 / 28 = 0.5 mol.</p><p>1 mol N<sub>2</sub> gives 2 mol NH<sub>3</sub>, so 0.5 mol gives 1 mol NH<sub>3</sub> = <b>17 g</b>.</p><p>34 g would come from 1 mol N<sub>2</sub>. Note that N<sub>2</sub> is 28 g mol<sup>-1</sup>, not 14.</p>', 'N<sub>2</sub> is a diatomic molecule: 28 g mol<sup>-1</sup>.'),
    mk('mc-017', 2, 'limiting reagent', '2 mol of H<sub>2</sub> and 2 mol of O<sub>2</sub> are mixed and react completely to form water. Which is the limiting reagent and how much water forms?', 'H<sub>2</sub>; 2 mol', ['O<sub>2</sub>; 2 mol', 'H<sub>2</sub>; 4 mol', 'O<sub>2</sub>; 1 mol'], '<p>2H<sub>2</sub> + O<sub>2</sub> → 2H<sub>2</sub>O. 2 mol H<sub>2</sub> needs only 1 mol O<sub>2</sub>. So O<sub>2</sub> is in excess (1 mol left) and H<sub>2</sub> is limiting.</p><p>2 mol H<sub>2</sub> gives <b>2 mol H<sub>2</sub>O</b>.</p>', 'Compare moles divided by the coefficient, not just the moles.'),
    nat('mc-018', 2, 'concentration terms', 'What is the molality of a solution made by dissolving 18 g of glucose (C<sub>6</sub>H<sub>12</sub>O<sub>6</sub>, 180 g mol<sup>-1</sup>) in 500 g of water?', 0.2, 0.005, 'mol kg<sup>-1</sup>', '<p>Moles of glucose = 18 / 180 = 0.1 mol.</p><p>Mass of solvent = 0.5 kg.</p><p>Molality = 0.1 / 0.5 = <b>0.2 mol kg<sup>-1</sup></b>. Molality uses kg of solvent, not solution.</p>'),
    mk('mc-019', 2, 'concentration terms', 'A mixture has 46 g of ethanol (C<sub>2</sub>H<sub>5</sub>OH) and 54 g of water. The mole fraction of ethanol is', '0.25', ['0.46', '0.50', '0.33'], '<p>Moles of ethanol = 46 / 46 = 1. Moles of water = 54 / 18 = 3.</p><p>x(ethanol) = 1 / (1 + 3) = <b>0.25</b>.</p><p>0.46 is the mass fraction, a different quantity.</p>'),
    nat('mc-020', 2, 'dilution', '100 mL of 2 M HCl is diluted with water to a total volume of 500 mL. What is the new molarity?', 0.4, 0.005, 'M', '<p>Moles of HCl do not change on dilution: M<sub>1</sub>V<sub>1</sub> = M<sub>2</sub>V<sub>2</sub>.</p><p>2 × 100 = M<sub>2</sub> × 500, so M<sub>2</sub> = <b>0.4 M</b>.</p>'),
    mk('mc-021', 2, 'mixing of solutions', 'On mixing 200 mL of 0.5 M HCl with 300 mL of 1.0 M HCl, the molarity of the mixture is', '0.8 M', ['0.75 M', '0.7 M', '1.5 M'], '<p>Total moles = 0.2 × 0.5 + 0.3 × 1.0 = 0.1 + 0.3 = 0.4 mol.</p><p>Total volume = 0.5 L (assume volumes add).</p><p>M = 0.4 / 0.5 = <b>0.8 M</b>. The simple average 0.75 M ignores the different volumes.</p>'),
    nat('mc-022', 2, 'percentage yield', 'The theoretical yield of a product is 40 g and the actual yield is 30 g. What is the percentage yield?', 75, 0, '%', '<p>Percentage yield = (actual / theoretical) × 100 = (30 / 40) × 100 = <b>75%</b>.</p>'),
    mk('mc-023', 2, 'atoms and molecules', 'How many atoms are present in 16 g of methane, CH<sub>4</sub>? (C = 12, H = 1)', '5 N<sub>A</sub>', ['N<sub>A</sub>', '4 N<sub>A</sub>', '16 N<sub>A</sub>'], '<p>16 g of CH<sub>4</sub> = 16 / 16 = 1 mol = N<sub>A</sub> molecules.</p><p>Each molecule has 1 + 4 = 5 atoms. Total = <b>5 N<sub>A</sub></b>.</p>'),
    mk('mc-024', 2, 'n-factor and equivalents', 'The n-factor of KMnO<sub>4</sub> when it acts in acidic medium and is reduced to Mn<sup>2+</sup> is', '5', ['1', '3', '7'], '<p>Mn goes from +7 in MnO<sub>4</sub><sup>-</sup> to +2 in Mn<sup>2+</sup>. It gains 5 electrons.</p><p>n-factor = <b>5</b>. (In neutral medium to MnO<sub>2</sub> it is 3; in strongly basic medium to MnO<sub>4</sub><sup>2-</sup> it is 1.)</p>'),
    mk('mc-025', 2, 'n-factor and equivalents', 'The equivalent mass of H<sub>2</sub>SO<sub>4</sub> in a complete neutralisation with NaOH is (H = 1, S = 32, O = 16)', '49', ['98', '24.5', '196'], '<p>H<sub>2</sub>SO<sub>4</sub> has 2 replaceable H<sup>+</sup>, so n-factor = 2.</p><p>Equivalent mass = molar mass / n-factor = 98 / 2 = <b>49</b>.</p>'),
    nat('mc-026', 2, 'eudiometry', '10 mL of methane is burnt with 40 mL of oxygen (excess). After the reaction the mixture is cooled to the initial temperature so water becomes liquid. What is the contraction in volume in mL? (CH<sub>4</sub> + 2O<sub>2</sub> → CO<sub>2</sub> + 2H<sub>2</sub>O)', 20, 0, 'mL', '<p>Gas volume before: 10 + 40 = 50 mL.</p><p>10 mL CH<sub>4</sub> uses 20 mL O<sub>2</sub> and gives 10 mL CO<sub>2</sub>. Left O<sub>2</sub> = 20 mL. Water is liquid and has negligible volume.</p><p>Gas after = 10 + 20 = 30 mL. Contraction = 50 - 30 = <b>20 mL</b>.</p>', 'Water vapour counts only if the question says the temperature stays high.'),
    mk('mc-027', 2, 'atomic mass', 'Chlorine has two isotopes, 35 (75%) and 37 (25%). The average atomic mass is', '35.5', ['36.0', '35.0', '36.5'], '<p>Weighted average = 0.75 × 35 + 0.25 × 37 = 26.25 + 9.25 = <b>35.5</b>.</p>'),
    nat('mc-028', 2, 'concentration terms', 'A 1 kg water sample contains 2 mg of dissolved fluoride. Treat the sample mass as 1 kg. What is the fluoride content in ppm by mass?', 2, 0, 'ppm', '<p>ppm = (mass of solute / mass of solution) × 10<sup>6</sup>.</p><p>2 mg = 2 × 10<sup>-3</sup> g; 1 kg = 10<sup>3</sup> g. Ratio = 2 × 10<sup>-6</sup>.</p><p>So the content is <b>2 ppm</b>.</p>'),
    mk('mc-029', 2, 'atoms and molecules', 'How many electrons are present in 1.8 g of water? (H = 1, O = 16; N<sub>A</sub> = 6.022 × 10<sup>23</sup>)', '6.022 × 10<sup>23</sup>', ['6.022 × 10<sup>22</sup>', '3.011 × 10<sup>23</sup>', '1.2044 × 10<sup>24</sup>'], '<p>1.8 g of water = 1.8 / 18 = 0.1 mol.</p><p>Each H<sub>2</sub>O has 2(1) + 8 = 10 electrons.</p><p>Electrons = 0.1 × 10 × N<sub>A</sub> = N<sub>A</sub> = <b>6.022 × 10<sup>23</sup></b>.</p>'),
    mk('mc-030', 2, 'stoichiometry', 'Heating 24.5 g of KClO<sub>3</sub> gives how much oxygen by 2KClO<sub>3</sub> → 2KCl + 3O<sub>2</sub>? (K = 39, Cl = 35.5, O = 16)', '9.6 g', ['6.4 g', '14.4 g', '3.2 g'], '<p>Molar mass of KClO<sub>3</sub> = 39 + 35.5 + 48 = 122.5. Moles = 24.5 / 122.5 = 0.2.</p><p>2 mol KClO<sub>3</sub> gives 3 mol O<sub>2</sub>, so 0.2 mol gives 0.3 mol O<sub>2</sub>.</p><p>Mass = 0.3 × 32 = <b>9.6 g</b>.</p>'),
    asr('mc-031', 2, 'concentration terms', 'The molality of a solution does not change when the temperature changes.', 'Molality is expressed in mol kg<sup>-1</sup>.', 1, '<p>A is true: molality uses masses only, and mass does not change with temperature (unlike volume).</p><p>R is true, but a unit does not explain the temperature behaviour. The real reason is that the denominator is the <i>mass</i> of solvent. So R is true but not the explanation: option 2.</p>'),
    stm('mc-032', 2, 'concentration terms', 'Molarity of a solution changes with temperature.', 'Molality of a solution is independent of temperature.', 0, '<p>Both are correct. Molarity has litres of solution in the denominator and volume changes with temperature. Molality has kg of solvent, so it does not change.</p>'),
    asr('mc-033', 2, 'molar mass', 'Equal masses of O<sub>2</sub> and O<sub>3</sub> contain the same number of oxygen atoms.', 'O<sub>2</sub> and O<sub>3</sub> have different molar masses.', 1, '<p>Take 48 g of each. Both are pure oxygen, so both contain 48 / 16 = 3 mol of O atoms. A is true.</p><p>R is true (32 and 48 g mol<sup>-1</sup>), but this does not explain A. The reason for A is that both are made only of oxygen atoms of mass 16. So: both true, R not the explanation.</p>', 'A true statement is not always the explanation.'),
    // ---------- Level 3 ----------
    nat('mc-034', 3, 'concentration terms', 'Concentrated sulphuric acid is 98% H<sub>2</sub>SO<sub>4</sub> by mass and has density 1.8 g mL<sup>-1</sup>. What is its molarity? (H<sub>2</sub>SO<sub>4</sub> = 98 g mol<sup>-1</sup>)', 18, 0, 'M', '<p>Idea: M = (10 × mass % × density) / molar mass.</p><p>Take 1 L = 1000 mL: mass = 1800 g. H<sub>2</sub>SO<sub>4</sub> in it = 0.98 × 1800 = 1764 g.</p><p>Moles = 1764 / 98 = 18. So the molarity is <b>18 M</b>.</p>', 'Density must be in g mL<sup>-1</sup> for the shortcut formula.'),
    nat('mc-035', 3, 'limiting reagent', 'When 11.2 g of iron and 3.2 g of sulphur are heated, Fe + S → FeS. What mass of FeS forms, in grams? (Fe = 56, S = 32)', 8.8, 0.05, 'g', '<p>Fe = 11.2 / 56 = 0.2 mol. S = 3.2 / 32 = 0.1 mol. They react 1 : 1.</p><p>Sulphur is limiting (0.1 mol), so FeS = 0.1 mol. Molar mass of FeS = 88.</p><p>Mass = 0.1 × 88 = <b>8.8 g</b>. (5.6 g Fe is left over.)</p>', 'The compound mass is based on the limiting reagent, not the larger amount.'),
    nat('mc-036', 3, 'hydrated salts', 'A hydrated salt CuSO<sub>4</sub>·xH<sub>2</sub>O loses 36.07% of its mass on heating to the anhydrous salt. Find x. (Cu = 63.5, S = 32, O = 16, H = 1)', 5, 0, '', '<p>Anhydrous CuSO<sub>4</sub> = 63.5 + 32 + 64 = 159.5. Let x water: mass of water = 18x.</p><p>18x / (159.5 + 18x) = 0.3607, so 18x = 0.3607 × 159.5 + 0.3607 × 18x.</p><p>18x × 0.6393 = 57.53, so 18x = 90.0 and x = <b>5</b>.</p>'),
    mk('mc-037', 3, 'combustion analysis', '0.58 g of a hydrocarbon on complete combustion gives 1.76 g CO<sub>2</sub> and 0.90 g H<sub>2</sub>O. If its molar mass is 58 g mol<sup>-1</sup>, its molecular formula is', 'C<sub>4</sub>H<sub>10</sub>', ['C<sub>2</sub>H<sub>5</sub>', 'C<sub>3</sub>H<sub>6</sub>', 'C<sub>4</sub>H<sub>8</sub>'], '<p>C = 1.76 × 12/44 = 0.48 g = 0.04 mol. H = 0.90 × 2/18 = 0.10 g = 0.10 mol. (0.48 + 0.10 = 0.58 g, so no oxygen.)</p><p>C : H = 0.04 : 0.10 = 2 : 5. Empirical formula C<sub>2</sub>H<sub>5</sub> (mass 29).</p><p>n = 58 / 29 = 2. Molecular formula = <b>C<sub>4</sub>H<sub>10</sub></b>.</p>', 'C<sub>2</sub>H<sub>5</sub> is only the empirical formula. Use the molar mass.'),
    mk('mc-038', 3, 'eudiometry', '10 mL of a gaseous hydrocarbon C<sub>x</sub>H<sub>y</sub> is exploded with 60 mL of O<sub>2</sub>. After cooling to the original temperature the volume is 45 mL, and after passing through KOH it is 15 mL. The hydrocarbon is', 'C<sub>3</sub>H<sub>6</sub>', ['C<sub>3</sub>H<sub>8</sub>', 'C<sub>2</sub>H<sub>6</sub>', 'C<sub>4</sub>H<sub>8</sub>'], '<p>KOH absorbs CO<sub>2</sub>: CO<sub>2</sub> = 45 - 15 = 30 mL. So x = 30 / 10 = 3.</p><p>Left over O<sub>2</sub> = 15 mL, so O<sub>2</sub> used = 45 mL = 10 × (x + y/4). So x + y/4 = 4.5, and y/4 = 1.5, y = 6.</p><p>The hydrocarbon is <b>C<sub>3</sub>H<sub>6</sub></b>.</p>', 'After cooling, water is liquid, so it is not in the gas volume.'),
    nat('mc-039', 3, 'n-factor and equivalents', 'How many moles of KMnO<sub>4</sub> are needed in acidic medium to oxidise 1 mol of FeC<sub>2</sub>O<sub>4</sub> completely (Fe<sup>2+</sup> to Fe<sup>3+</sup> and C<sub>2</sub>O<sub>4</sub><sup>2-</sup> to CO<sub>2</sub>)?', 0.6, 0.005, 'mol', '<p>Electrons lost per FeC<sub>2</sub>O<sub>4</sub>: Fe<sup>2+</sup> to Fe<sup>3+</sup> = 1; C<sub>2</sub>O<sub>4</sub><sup>2-</sup> to 2CO<sub>2</sub> = 2. n-factor = 3.</p><p>KMnO<sub>4</sub> gains 5 per mole. Equivalents match: 1 × 3 = x × 5, so x = <b>0.6 mol</b>.</p>', 'Both Fe and the oxalate are oxidised: add the two changes.'),
    mk('mc-040', 3, 'n-factor and equivalents', 'The normality of 0.2 M Ba(OH)<sub>2</sub> as a base is', '0.4 N', ['0.2 N', '0.1 N', '0.6 N'], '<p>Ba(OH)<sub>2</sub> gives 2 OH<sup>-</sup>, so n-factor = 2. N = M × n = 0.2 × 2 = <b>0.4 N</b>.</p>'),
    nat('mc-041', 3, 'mixing of solutions', '100 mL of 0.1 M HCl is mixed with 100 mL of 0.2 M NaOH. What is the molarity of the OH<sup>-</sup> ions left in the mixture?', 0.05, 0.001, 'M', '<p>Moles HCl = 0.01. Moles NaOH = 0.02. They react 1 : 1, so 0.01 mol NaOH is left.</p><p>Total volume = 0.2 L. [OH<sup>-</sup>] = 0.01 / 0.2 = <b>0.05 M</b>.</p>', 'Use the total volume (200 mL), not just 100 mL.'),
    nat('mc-042', 3, 'concentration terms', 'In a 1.00 molal aqueous solution, what is the mole fraction of the solute? (Take water = 18 g mol<sup>-1</sup>; give your answer to 4 decimal places)', 0.0177, 0.0003, '', '<p>1 molal means 1 mol solute in 1000 g water.</p><p>Moles of water = 1000 / 18 = 55.56.</p><p>x(solute) = 1 / (1 + 55.56) = <b>0.0177</b>.</p>'),
    nat('mc-043', 3, 'average molar mass', 'A gas mixture contains 1 mol of O<sub>2</sub> and 3 mol of N<sub>2</sub>. What is the average molar mass of the mixture in g mol<sup>-1</sup>? (O = 16, N = 14)', 29, 0, 'g mol<sup>-1</sup>', '<p>Average molar mass = total mass / total moles.</p><p>Mass = 1 × 32 + 3 × 28 = 116 g. Moles = 4.</p><p>M = 116 / 4 = <b>29</b>.</p>'),
    mk('mc-044', 3, 'vapour density', 'A gas has vapour density 22. How many moles are present in 11 g of it?', '0.25', ['0.5', '0.125', '1'], '<p>Molar mass = 2 × vapour density = 44 g mol<sup>-1</sup>.</p><p>Moles = 11 / 44 = <b>0.25</b>.</p><p>0.5 comes from using 22 as the molar mass.</p>', 'Vapour density is relative to hydrogen gas H<sub>2</sub>. M = 2 × VD.'),
    nat('mc-045', 3, 'percentage composition', 'What is the percentage of nitrogen by mass in ammonium sulphate, (NH<sub>4</sub>)<sub>2</sub>SO<sub>4</sub>? (N = 14, H = 1, S = 32, O = 16) Give the answer to 1 decimal place.', 21.2, 0.1, '%', '<p>Molar mass = 2(14 + 4) + 32 + 64 = 36 + 96 = 132.</p><p>Nitrogen = 2 × 14 = 28.</p><p>% N = (28 / 132) × 100 = <b>21.2%</b>.</p>'),
    nat('mc-046', 3, 'preparing solutions', 'What mass of anhydrous Na<sub>2</sub>CO<sub>3</sub> is needed to make 250 mL of 0.2 M solution? (Na = 23, C = 12, O = 16)', 5.3, 0.05, 'g', '<p>Moles needed = 0.2 × 0.25 = 0.05 mol.</p><p>Molar mass = 46 + 12 + 48 = 106.</p><p>Mass = 0.05 × 106 = <b>5.3 g</b>.</p>'),
    nat('mc-047', 3, 'concentration terms', 'Water with hardness of 100 ppm is expressed as 100 mg of CaCO<sub>3</sub> per litre (treat 1 L as 1 kg). Its molarity in CaCO<sub>3</sub> is x × 10<sup>-3</sup> M. Find x. (CaCO<sub>3</sub> = 100)', 1, 0, '', '<p>100 mg = 0.1 g. Moles = 0.1 / 100 = 10<sup>-3</sup> mol in 1 L.</p><p>So the molarity = 1 × 10<sup>-3</sup> M, and x = <b>1</b>.</p>'),
    mk('mc-048', 3, 'atoms and molecules', 'How many molecules are present in 1 mL of water? (density 1 g mL<sup>-1</sup>; N<sub>A</sub> = 6.022 × 10<sup>23</sup>)', '3.35 × 10<sup>22</sup>', ['6.022 × 10<sup>23</sup>', '5.55 × 10<sup>-2</sup>', '3.35 × 10<sup>23</sup>'], '<p>1 mL of water = 1 g = 1/18 mol = 0.0556 mol.</p><p>Molecules = 0.0556 × 6.022 × 10<sup>23</sup> = <b>3.35 × 10<sup>22</sup></b>.</p>'),
    nat('mc-049', 3, 'stoichiometry', 'What volume of O<sub>2</sub> at 273 K and 1 atm is obtained from 24.5 g of KClO<sub>3</sub> on complete decomposition (2KClO<sub>3</sub> → 2KCl + 3O<sub>2</sub>)? Give the answer in litres. (K = 39, Cl = 35.5, O = 16)', 6.72, 0.05, 'L', '<p>Moles KClO<sub>3</sub> = 24.5 / 122.5 = 0.2. O<sub>2</sub> = 0.2 × 3/2 = 0.3 mol.</p><p>Volume = 0.3 × 22.4 = <b>6.72 L</b>.</p>'),
    mk('mc-050', 3, 'ions in solution', '500 mL of 0.1 M Al<sub>2</sub>(SO<sub>4</sub>)<sub>3</sub> is prepared. Assuming complete dissociation, how many moles of ions (Al<sup>3+</sup> and SO<sub>4</sub><sup>2-</sup> together) does it contain?', '0.25 mol', ['0.05 mol', '0.15 mol', '0.5 mol'], '<p>Moles of salt = 0.1 × 0.5 = 0.05 mol.</p><p>Each formula unit gives 2 Al<sup>3+</sup> + 3 SO<sub>4</sub><sup>2-</sup> = 5 ions.</p><p>Ions = 0.05 × 5 = <b>0.25 mol</b>. (0.5 mol is for 1 L.)</p>'),
    nat('mc-051', 3, 'equivalent mass', '0.56 g of a metal reacts with an acid and releases 224 mL of H<sub>2</sub> at 273 K and 1 atm. What is the equivalent mass of the metal?', 28, 0, '', '<p>H<sub>2</sub> = 0.224 / 22.4 = 0.01 mol = 0.02 gram equivalents (each H<sub>2</sub> takes 2 electrons).</p><p>Equivalent mass = 0.56 / 0.02 = <b>28</b>. (This fits Fe in Fe<sup>2+</sup>: 56 / 2.)</p>'),
    mk('mc-052', 3, 'mixed gas and moles', 'Which of the following contains the largest number of atoms?', '8 g of CH<sub>4</sub>', ['11 g of CO<sub>2</sub>', '9 g of H<sub>2</sub>O', '7 g of N<sub>2</sub>'], '<p>Count atoms = moles × atoms per molecule.</p><p>8 g CH<sub>4</sub>: 0.5 mol × 5 = 2.5 mol atoms. 11 g CO<sub>2</sub>: 0.25 × 3 = 0.75. 9 g H<sub>2</sub>O: 0.5 × 3 = 1.5. 7 g N<sub>2</sub>: 0.25 × 2 = 0.5.</p><p>The largest is <b>8 g of CH<sub>4</sub></b>.</p>', 'Do not pick the largest mass or the largest number of molecules; count atoms.'),
    mk('mc-053', 3, 'percentage yield', 'In a two-step process A → B (80% yield) then B → C (50% yield), what mass of C is obtained from a quantity of A that would theoretically give 100 g of C?', '40 g', ['65 g', '30 g', '60 g'], '<p>The overall yield = 0.80 × 0.50 = 0.40 = 40%.</p><p>Mass of C = 100 × 0.40 = <b>40 g</b>.</p><p>Adding or averaging (65%) is wrong: yields multiply for steps in series.</p>', 'Yields of consecutive steps multiply.'),
    asr('mc-054', 3, 'limiting reagent', 'The limiting reagent decides how much product can form.', 'The reagent present in the smallest mass is always the limiting reagent.', 2, '<p>A is true: the reagent that runs out first stops the reaction.</p><p>R is false. Limiting depends on moles and coefficients, not on mass. Example: 2 g of H<sub>2</sub> (1 mol) and 4 g of O<sub>2</sub> (0.125 mol) for 2H<sub>2</sub> + O<sub>2</sub> → 2H<sub>2</sub>O. H<sub>2</sub> has the smaller mass, but 0.125 mol O<sub>2</sub> needs only 0.25 mol H<sub>2</sub>, so H<sub>2</sub> is in excess and O<sub>2</sub> is the limiting reagent.</p>', 'Convert masses to moles and divide by the coefficient.'),
    asr('mc-055', 3, 'concentration terms', 'A 1 M solution is made by dissolving 1 mol of solute in 1 L of solvent.', 'Molarity is the number of moles of solute per litre of solution.', 3, '<p>A is false. The 1 L is the volume of the <i>solution</i>, so you dissolve 1 mol in some solvent and add solvent until the total volume is 1 L.</p><p>R is the correct definition of molarity. So A is false and R is true.</p>', 'Solution and solvent are different.'),
    stm('mc-056', 3, 'molar volume', '1 mol of any ideal gas occupies 22.4 L at 273 K and 1 atm.', '1 mol of any substance occupies 22.4 L at 273 K and 1 atm.', 1, '<p>I is correct for an ideal gas.</p><p>II is incorrect. Liquids and solids have very different molar volumes (1 mol of water is about 18 mL; 1 mol of iron about 7 cm<sup>3</sup>). The 22.4 L is only for gases.</p>'),
    stm('mc-057', 3, 'moles of atoms', '12 g of magnesium has the same number of atoms as 12 g of carbon.', '1 mol of atoms of any element contains the same number of atoms.', 2, '<p>I is incorrect: 12 g Mg = 0.5 mol (Mg = 24), while 12 g C = 1 mol. They do not have the same number.</p><p>II is correct: 1 mol always means N<sub>A</sub> atoms. The two statements look like they agree, but equal <i>mass</i> is not equal <i>moles</i>.</p>', 'Equal mass is not equal moles.'),
    stm('mc-058', 3, 'laws of chemical combination', 'Dalton\'s atomic theory could fully explain Gay-Lussac\'s law of combining volumes.', 'Avogadro\'s hypothesis, with molecules of gases like H<sub>2</sub> and O<sub>2</sub> being diatomic, explains Gay-Lussac\'s law.', 2, '<p>I is incorrect: Dalton assumed that gases like hydrogen were single atoms, which gave a wrong number of volumes for water vapour.</p><p>II is correct: Avogadro\'s idea of equal volumes with equal molecules and diatomic molecules fixed this.</p>'),
    mk('mc-059', 3, 'conservation of mass', '1 g of CaCO<sub>3</sub> is heated strongly in an open dish and the solid residue weighs 0.56 g. What mass of gas escaped, and what does the experiment suggest for the law of conservation of mass?', '0.44 g; the law holds when the escaped gas is counted', ['0.44 g; the law is violated', '0.56 g; the law holds', '1.00 g; the law is violated'], '<p>CaCO<sub>3</sub> → CaO + CO<sub>2</sub>. Mass lost = 1.00 - 0.56 = 0.44 g, which is CO<sub>2</sub> (44 g per mole, and 0.01 mol).</p><p>The total mass of reactants equals the total mass of products only if the escaped CO<sub>2</sub> is counted. So the law is <b>not violated</b>.</p>', 'In an open vessel, gases escape.'),
    nat('mc-060', 3, 'concentration terms', 'A solution of H<sub>3</sub>PO<sub>4</sub> is 0.1 M. If it is used in a reaction in which all three H<sup>+</sup> are replaced, its normality is x × 10<sup>-1</sup>. Find x.', 3, 0, '', '<p>N = M × n-factor = 0.1 × 3 = 0.3 N = 3 × 10<sup>-1</sup>.</p><p>So x = <b>3</b>. (If only 2 H<sup>+</sup> react, the normality would be 0.2 N: the n-factor depends on the reaction.)</p>', 'n-factor for acids is the number of H<sup>+</sup> actually replaced.'),
    mat('mc-061', 3, 'atoms and molecules', 'm1', 'Match the samples in List I with their masses in List II. (C = 12, H = 1, N = 14, O = 16, Ca = 40)', 'A-q, B-s, C-p, D-r', ['A-s, B-q, C-r, D-p', 'A-p, B-q, C-s, D-r', 'A-q, B-p, C-s, D-r'], '<p>A: 0.25 × 16 = 4 g (q). B: 11.2 L = 0.5 mol N<sub>2</sub> × 28 = 14 g (s). C: 3.011 × 10<sup>23</sup> = 0.5 mol H<sub>2</sub>O × 18 = 9 g (p). D: 0.1 × 100 = 10 g (r).</p><p>So A-q, B-s, C-p, D-r.</p>'),
    mat('mc-062', 3, 'laws of chemical combination', 'm2', 'Match each law in List I with the best example in List II.', 'A-q, B-p, C-r, D-s', ['A-p, B-q, C-r, D-s', 'A-q, B-p, C-s, D-r', 'A-r, B-p, C-q, D-s'], '<p>A: definite proportions is the fixed H : O = 1 : 8 in water (q). B: multiple proportions is CO and CO<sub>2</sub> with 16 g and 32 g of oxygen per 12 g C (p). C: Gay-Lussac is volumes 2 : 1 : 2 (r). D: conservation of mass is the sealed jar (s).</p>'),
    // ---------- Level 4 ----------
    nat('mc-063', 4, 'oleum', 'Oleum (H<sub>2</sub>SO<sub>4</sub> with dissolved SO<sub>3</sub>) is labelled "118%". This means 100 g of the oleum, on adding enough water, gives 118 g of pure H<sub>2</sub>SO<sub>4</sub>. What is the percentage by mass of free SO<sub>3</sub> in it? (S = 32, O = 16)', 80, 0, '%', '<p>SO<sub>3</sub> + H<sub>2</sub>O → H<sub>2</sub>SO<sub>4</sub>. The extra mass is 118 - 100 = 18 g of water, which is 1 mol.</p><p>1 mol water reacts with 1 mol SO<sub>3</sub> = 80 g. So the 100 g sample has <b>80 g SO<sub>3</sub></b>, i.e. 80% (and 20 g H<sub>2</sub>SO<sub>4</sub>).</p><p>Check: 80 g SO<sub>3</sub> gives 98 g; 98 + 20 = 118 g. ✓</p>', 'A label above 100% is not an error; it tells how much acid the oleum can make.'),
    nat('mc-064', 4, 'mixture analysis', 'A 9.2 g mixture of CaCO<sub>3</sub> and MgCO<sub>3</sub> is heated until it gives 4.4 g of CO<sub>2</sub>. What is the mass of CaCO<sub>3</sub> in the mixture, in grams? (Ca = 40, Mg = 24, C = 12, O = 16)', 5, 0.05, 'g', '<p>Let CaCO<sub>3</sub> = x g. Then MgCO<sub>3</sub> = 9.2 - x. Each mole gives 1 mol CO<sub>2</sub> (44 g). CaCO<sub>3</sub> = 100, MgCO<sub>3</sub> = 84.</p><p>Moles of CO<sub>2</sub> = x/100 + (9.2 - x)/84 = 4.4/44 = 0.1.</p><p>Multiply by 8400: 84x + 100(9.2 - x) = 840. So 920 - 16x = 840 and x = <b>5 g</b>.</p><p>Check: 5/100 + 4.2/84 = 0.05 + 0.05 = 0.1 ✓.</p>'),
    nat('mc-065', 4, 'n-factor and equivalents', 'Chlorine disproportionates in hot alkali: 3Cl<sub>2</sub> + 6OH<sup>-</sup> → 5Cl<sup>-</sup> + ClO<sub>3</sub><sup>-</sup> + 3H<sub>2</sub>O. What is the n-factor of Cl<sub>2</sub> in this reaction? Give the answer to 2 decimals.', 1.67, 0.01, '', '<p>Look at electrons for 3 mol of Cl<sub>2</sub> (6 Cl atoms).</p><p>5 Cl go from 0 to -1: gain 5 electrons. 1 Cl goes from 0 to +5: loses 5 electrons.</p><p>Only the electrons lost (or gained, same number) are counted: 5 electrons per 3 mol Cl<sub>2</sub>.</p><p>n-factor = 5/3 = <b>1.67</b>.</p>', 'In disproportionation count the electrons lost only (or gained only), not both.'),
    nat('mc-066', 4, 'redox titration', '20 mL of 0.1 M KMnO<sub>4</sub> in acidic medium exactly reacts with V mL of 0.25 M oxalic acid (H<sub>2</sub>C<sub>2</sub>O<sub>4</sub>). Find V in mL.', 20, 0, 'mL', '<p>Equivalents: KMnO<sub>4</sub> n = 5, so 0.1 M = 0.5 N. Oxalic acid n = 2, so 0.25 M = 0.5 N.</p><p>N<sub>1</sub>V<sub>1</sub> = N<sub>2</sub>V<sub>2</sub>: 0.5 × 20 = 0.5 × V, so V = <b>20 mL</b>.</p><p>Mole check: 2 mmol KMnO<sub>4</sub> reacts with 5 mmol oxalic acid (2MnO<sub>4</sub><sup>-</sup> : 5H<sub>2</sub>C<sub>2</sub>O<sub>4</sub>). 5 mmol / 0.25 M = 20 mL ✓.</p>', 'The numbers match only because both are 0.5 N. A mole ratio of 1 : 1 would have given a different answer.'),
    nat('mc-067', 4, 'H2O2 strength', 'A "20 volume" H<sub>2</sub>O<sub>2</sub> solution gives 20 L of O<sub>2</sub> at 273 K and 1 atm from 1 L of the solution (2H<sub>2</sub>O<sub>2</sub> → 2H<sub>2</sub>O + O<sub>2</sub>). What is its molarity? Give the answer to 2 decimals.', 1.79, 0.01, 'M', '<p>O<sub>2</sub> = 20 / 22.4 = 0.893 mol.</p><p>2 mol H<sub>2</sub>O<sub>2</sub> gives 1 mol O<sub>2</sub>, so H<sub>2</sub>O<sub>2</sub> = 2 × 0.893 = 1.786 mol per litre.</p><p>Molarity = <b>1.79 M</b>. (Shortcut: M = V / 11.2.)</p>', 'Using 22.4 / 1 instead of 22.4 / 2 gives 0.89 M.'),
    nat('mc-068', 4, 'concentration terms', 'A 3.00 M aqueous urea solution (urea = 60 g mol<sup>-1</sup>) has density 1.20 g mL<sup>-1</sup>. What is its molality in mol kg<sup>-1</sup>? Give the answer to 2 decimals.', 2.94, 0.02, 'mol kg<sup>-1</sup>', '<p>Take 1 L of solution. Mass = 1200 g. Urea = 3 × 60 = 180 g.</p><p>Solvent mass = 1200 - 180 = 1020 g = 1.020 kg.</p><p>Molality = 3 / 1.020 = <b>2.94 mol kg<sup>-1</sup></b>.</p>', 'Subtract the solute mass to get the solvent mass.'),
    nat('mc-069', 4, 'Kjeldahl method', 'In Kjeldahl\'s method, the ammonia from 0.300 g of an organic compound neutralised 20.0 mL of 0.100 N H<sub>2</sub>SO<sub>4</sub>. What is the percentage of nitrogen in the compound? (N = 14)', 9.33, 0.05, '%', '<p>Milliequivalents of acid = 20 × 0.1 = 2 meq. NH<sub>3</sub> takes 1 eq per mole, so 2 mmol NH<sub>3</sub> = 2 mmol N.</p><p>Mass of N = 2 × 14 = 28 mg = 0.028 g.</p><p>% N = 0.028 / 0.300 × 100 = <b>9.33%</b>.</p>', 'The meq of acid equals the mmol of NH<sub>3</sub>, since NH<sub>3</sub> accepts only one H<sup>+</sup>.'),
    nat('mc-070', 4, 'limiting reagent', '5.4 g of aluminium is burnt with 3.2 g of oxygen: 4Al + 3O<sub>2</sub> → 2Al<sub>2</sub>O<sub>3</sub>. What mass of Al<sub>2</sub>O<sub>3</sub> forms, in grams? (Al = 27, O = 16)', 6.8, 0.05, 'g', '<p>Al = 5.4 / 27 = 0.2 mol. O<sub>2</sub> = 3.2 / 32 = 0.1 mol.</p><p>Al needs 0.2 × 3/4 = 0.15 mol O<sub>2</sub>, but only 0.1 mol is there. So O<sub>2</sub> is limiting.</p><p>Al<sub>2</sub>O<sub>3</sub> = 0.1 × 2/3 = 0.0667 mol. Molar mass = 102.</p><p>Mass = 0.0667 × 102 = <b>6.8 g</b>.</p>'),
    nat('mc-071', 4, 'atomic mass', 'Boron has two isotopes, <sup>10</sup>B and <sup>11</sup>B. The average atomic mass is 10.8. What is the percentage abundance of <sup>10</sup>B?', 20, 0, '%', '<p>Let the fraction of <sup>10</sup>B be x. Then 10x + 11(1 - x) = 10.8.</p><p>11 - x = 10.8, so x = 0.2.</p><p>Abundance = <b>20%</b>. (The average is close to 11 because most atoms are <sup>11</sup>B.)</p>'),
    asr('mc-072', 4, 'H2O2 strength', 'A 1 M solution of H<sub>2</sub>O<sub>2</sub> has a volume strength of 11.2.', '1 mol of H<sub>2</sub>O<sub>2</sub> releases 0.5 mol of O<sub>2</sub>, which is 11.2 L at 273 K and 1 atm.', 0, '<p>2H<sub>2</sub>O<sub>2</sub> → 2H<sub>2</sub>O + O<sub>2</sub>. So 1 mol of H<sub>2</sub>O<sub>2</sub> gives 0.5 mol O<sub>2</sub> = 11.2 L at STP. A 1 M solution has 1 mol per litre, so its volume strength is 11.2. A is true, R is true and R is exactly why.</p>'),
    asr('mc-073', 4, 'n-factor and equivalents', 'In acidic medium, the n-factor of KMnO<sub>4</sub> is 5.', 'Manganese in KMnO<sub>4</sub> is in the +7 oxidation state.', 1, '<p>A is true: MnO<sub>4</sub><sup>-</sup> goes to Mn<sup>2+</sup>, so 7 - 2 = 5 electrons.</p><p>R is true, but the +7 state alone does not fix the n-factor. The <i>product</i> (+2 in acid) does. In neutral medium, from the same +7, the n-factor is 3. So R is true but not the explanation.</p>', 'The same reactant can have different n-factors in different media.'),
    stm('mc-074', 4, 'n-factor and equivalents', 'The equivalent mass of KMnO<sub>4</sub> in acidic medium is M/5.', 'The equivalent mass of KMnO<sub>4</sub> in strongly basic medium (to MnO<sub>4</sub><sup>2-</sup>) is M/3.', 1, '<p>I is correct (n = 5).</p><p>II is incorrect: MnO<sub>4</sub><sup>-</sup> to MnO<sub>4</sub><sup>2-</sup> is Mn +7 to +6, one electron. The equivalent mass is M/1 = M. M/3 is for the neutral or weakly basic medium (to MnO<sub>2</sub>).</p>'),
    stm('mc-075', 4, 'atomic mass', 'One atomic mass unit (1 u) is exactly the mass of one hydrogen atom.', 'The atomic mass of every element is a whole number.', 3, '<p>I is incorrect: 1 u is 1/12 of the mass of a carbon-12 atom, which is 1.66 × 10<sup>-24</sup> g. A hydrogen atom is 1.008 u.</p><p>II is incorrect: elements are mixtures of isotopes, so average atomic masses are not whole numbers (e.g. Cl = 35.5). Even single isotopes have mass defects.</p>'),
    { id: 'mc-076', type: 'mcq', level: 4, format: 'statements', exams: EX[4], sub: 'concentration terms', q: '<p>How many of the following statements are correct?</p><ol><li>The sum of the mole fractions of all components of a solution is 1.</li><li>1 M and 1 m aqueous solutions of glucose have the same concentration.</li><li>The molarity of pure water at about 4 °C is close to 55.5 M.</li><li>Mass percentage of a solute changes when the solution is heated.</li></ol>', options: ['1', '2', '3', '4'], answer: 1, sol: '<p>(1) True. (2) False: 1 m has 1 mol in 1 kg of water (about 1.08 L of solution for glucose), while 1 M has 1 mol in 1 L of solution, so they are different. (3) True: 1000 g / 18 = 55.5 mol in about 1 L. (4) False: mass does not change with temperature, so mass % does not.</p><p>Correct statements: 1 and 3. That is <b>2</b>.</p>', trap: 'Molarity and molality are only close for dilute aqueous solutions, and even then they are not equal.' },
    msq('mc-077', 4, 'atoms and molecules', 'Which of the following contain 3 N<sub>A</sub> atoms in total? (C = 12, H = 1, N = 14, O = 16)', ['44 g of CO<sub>2</sub>', '48 g of O<sub>3</sub>', '17 g of NH<sub>3</sub>', '18 g of H<sub>2</sub>O'], [0, 1, 3], '<p>A: 44 g CO<sub>2</sub> = 1 mol × 3 atoms = 3 N<sub>A</sub> ✓. B: 48 g O<sub>3</sub> = 1 mol × 3 atoms = 3 N<sub>A</sub> ✓. C: 17 g NH<sub>3</sub> = 1 mol × 4 atoms = 4 N<sub>A</sub> ✗. D: 18 g H<sub>2</sub>O = 1 mol × 3 = 3 N<sub>A</sub> ✓.</p><p>Answer: A, B and D.</p>', 'Ozone has three atoms per molecule.'),
    msq('mc-078', 4, 'concentration terms', 'Which of the following concentration terms do not change with temperature?', ['Molarity', 'Molality', 'Mole fraction', 'Normality', 'Mass percentage (w/w)'], [1, 2, 4], '<p>Molarity and normality have volume of solution in the denominator. Volume changes with temperature (expansion), so they change.</p><p>Molality (kg solvent), mole fraction (moles) and mass % (mass) use only masses or amounts, which do not change with temperature.</p><p>Answer: B, C and E.</p>'),
    msq('mc-079', 4, 'empirical formula', 'Which of the following compounds have the empirical formula CH<sub>2</sub>O?', ['HCHO (methanal)', 'CH<sub>3</sub>COOH (ethanoic acid)', 'C<sub>6</sub>H<sub>12</sub>O<sub>6</sub> (glucose)', 'C<sub>2</sub>H<sub>5</sub>OH (ethanol)'], [0, 1, 2], '<p>HCHO is CH<sub>2</sub>O already. CH<sub>3</sub>COOH is C<sub>2</sub>H<sub>4</sub>O<sub>2</sub>, ratio 1 : 2 : 1. Glucose is 6 : 12 : 6, ratio 1 : 2 : 1. Ethanol is C<sub>2</sub>H<sub>6</sub>O, ratio 1 : 3 : 0.5 and does not match.</p><p>Answer: A, B and C.</p>'),
    msq('mc-080', 4, 'stoichiometry', '2 mol of H<sub>2</sub> and 1 mol of O<sub>2</sub> are mixed and react completely to form water. Which statements are correct? (H = 1, O = 16)', ['2 mol of water are formed', 'There is no limiting reagent', '36 g of water are formed', 'The volume of steam formed (same T and P) equals the total volume of the reactants'], [0, 1, 2], '<p>2H<sub>2</sub> + O<sub>2</sub> → 2H<sub>2</sub>O in exactly these amounts. So 2 mol water = 36 g, and both reagents are used up (no limiting reagent or excess).</p><p>D is wrong: 3 volumes of gas give 2 volumes of steam (at the same T, P), a contraction by one third.</p><p>Answer: A, B and C.</p>'),
    msq('mc-081', 4, 'concentration terms', 'A 1 L solution is 0.1 M H<sub>2</sub>SO<sub>4</sub> (complete dissociation, H<sub>2</sub>SO<sub>4</sub> = 98). Which are correct?', ['Its normality for complete neutralisation is 0.2 N', 'It contains 0.1 mol of H<sub>2</sub>SO<sub>4</sub>', 'It contains 0.2 mol of H<sup>+</sup>', 'It contains 4.9 g of H<sub>2</sub>SO<sub>4</sub>'], [0, 1, 2], '<p>N = 0.1 × 2 = 0.2 N ✓. Moles = 0.1 × 1 = 0.1 ✓. H<sup>+</sup> = 0.2 mol ✓. Mass = 0.1 × 98 = 9.8 g, so D (4.9 g) is wrong; 4.9 g would be 0.05 mol.</p><p>Answer: A, B and C.</p>'),
    msq('mc-082', 4, 'H2O2 strength', 'Which of the following are correct for hydrogen peroxide (H<sub>2</sub>O<sub>2</sub> = 34)?', ['Its n-factor is 2 when it acts as an oxidising agent (to H<sub>2</sub>O)', 'Its n-factor is 2 when it acts as a reducing agent (to O<sub>2</sub>)', 'Its equivalent mass is 17 in both cases', 'A 1 M solution has a volume strength of 22.4'], [0, 1, 2], '<p>As an oxidant: each O goes from -1 to -2, two O, so 2 electrons. As a reductant: each O goes from -1 to 0, so 2 electrons. Equivalent mass = 34 / 2 = 17 in both cases.</p><p>D is false: 1 M gives 0.5 mol O<sub>2</sub> per litre = 11.2 L, so volume strength 11.2.</p><p>Answer: A, B and C.</p>'),
    mat('mc-083', 4, 'n-factor and equivalents', 'm3', 'Match the change in List I with its n-factor in List II (per formula unit written).', 'A-r, B-q, C-s, D-p', ['A-q, B-r, C-s, D-p', 'A-r, B-q, C-p, D-s', 'A-s, B-q, C-r, D-p'], '<p>A: Mn +7 to +2 = 5 electrons (r). B: Mn +7 to +4 = 3 (q). C: Cr<sub>2</sub>O<sub>7</sub><sup>2-</sup> has two Cr, each +6 to +3: 2 × 3 = 6 (s). D: H<sub>2</sub>C<sub>2</sub>O<sub>4</sub> has 2 carbons, each +3 to +4: 2 electrons (p).</p>', 'In dichromate there are two chromium atoms.'),
    nat('mc-084', 4, 'eudiometry', 'A 20 mL mixture of CH<sub>4</sub> and C<sub>2</sub>H<sub>6</sub> is burnt in excess oxygen. After the products are cooled to the initial temperature (water liquid), the total contraction in volume is 44 mL. What is the volume of CH<sub>4</sub> in the mixture, in mL?', 12, 0, 'mL', '<p>CH<sub>4</sub> + 2O<sub>2</sub> → CO<sub>2</sub> + 2H<sub>2</sub>O(l): 3 volumes of gas become 1, contraction per mL = 2.</p><p>C<sub>2</sub>H<sub>6</sub> + 3.5O<sub>2</sub> → 2CO<sub>2</sub> + 3H<sub>2</sub>O(l): 4.5 volumes become 2, contraction per mL = 2.5.</p><p>Let CH<sub>4</sub> = a, C<sub>2</sub>H<sub>6</sub> = b. a + b = 20 and 2a + 2.5b = 44.</p><p>Substitute: 2a + 2.5(20 - a) = 44, so 50 - 0.5a = 44, a = <b>12 mL</b> (b = 8 mL).</p>', 'Contraction here counts only the gases: the sum of reactant volumes minus the sum of gaseous products.'),
    nat('mc-085', 4, 'gas density and molar mass', 'A gas has a density of 2.40 g L<sup>-1</sup> at 27 °C and 2.00 atm. What is its molar mass? (R = 0.0821 L atm K<sup>-1</sup> mol<sup>-1</sup>)', 29.6, 0.4, 'g mol<sup>-1</sup>', '<p>For an ideal gas, PM = dRT.</p><p>M = dRT / P = 2.40 × 0.0821 × 300 / 2.00 = <b>29.6 g mol<sup>-1</sup></b>.</p><p>(Temperature must be in kelvin: 27 + 273 = 300 K.)</p>', 'Do not use 27 for T.'),
    // ---------- Level 5 ----------
    nat('mc-086', 5, 'redox titration', '20 mL of a solution containing both Fe<sup>2+</sup> and Fe<sup>3+</sup> needs 10.0 mL of 0.020 M KMnO<sub>4</sub> (acidic) for oxidation. Another 20 mL portion is first treated with zinc to reduce all Fe<sup>3+</sup> to Fe<sup>2+</sup>, and then needs 25.0 mL of the same KMnO<sub>4</sub>. What is the ratio [Fe<sup>3+</sup>] : [Fe<sup>2+</sup>] in the original solution?', 1.5, 0.01, '', '<p>MnO<sub>4</sub><sup>-</sup> + 5Fe<sup>2+</sup> → Mn<sup>2+</sup> + 5Fe<sup>3+</sup>, so 1 mmol KMnO<sub>4</sub> oxidises 5 mmol Fe<sup>2+</sup>.</p><p>First portion: KMnO<sub>4</sub> = 10 × 0.02 = 0.2 mmol, so Fe<sup>2+</sup> = 1.0 mmol.</p><p>Second portion: KMnO<sub>4</sub> = 25 × 0.02 = 0.5 mmol, so total Fe = 2.5 mmol.</p><p>Fe<sup>3+</sup> = 2.5 - 1.0 = 1.5 mmol. Ratio = 1.5 / 1.0 = <b>1.5</b>.</p>', 'The second titration measures total iron, not just Fe<sup>3+</sup>.'),
    nat('mc-087', 5, 'mixed: solids and moles', 'Wüstite is a non-stoichiometric oxide with the formula Fe<sub>0.90</sub>O. It contains Fe<sup>2+</sup> and Fe<sup>3+</sup> ions only. What percentage of the iron is present as Fe<sup>3+</sup>? Give the answer to 1 decimal place.', 22.2, 0.1, '%', '<p>Per 1 oxide ion (charge -2) there is 0.90 Fe in total. Let Fe<sup>3+</sup> = b and Fe<sup>2+</sup> = a.</p><p>a + b = 0.90 and charge balance 2a + 3b = 2.</p><p>2(0.90) + b = 2, so b = 0.20 and a = 0.70.</p><p>% Fe<sup>3+</sup> = 0.20 / 0.90 × 100 = <b>22.2%</b>.</p>', 'Charge balance and the ion ratio give two equations.'),
    nat('mc-088', 5, 'mixed: atomic structure', 'How many neutrons are present in 4.4 g of <sup>12</sup>C<sup>16</sup>O<sub>2</sub>? Give the answer in units of N<sub>A</sub> (that is, as moles of neutrons).', 2.2, 0.02, 'N<sub>A</sub>', '<p>Neutrons = mass number - atomic number. <sup>12</sup>C: 12 - 6 = 6. <sup>16</sup>O: 16 - 8 = 8.</p><p>One CO<sub>2</sub> molecule has 6 + 2 × 8 = 22 neutrons.</p><p>Molar mass of this CO<sub>2</sub> = 12 + 32 = 44, so 4.4 g = 0.1 mol.</p><p>Neutrons = 0.1 × 22 = <b>2.2 N<sub>A</sub></b>.</p>', 'Protons and electrons are 22 per molecule too, but neutrons are the question.'),
    nat('mc-089', 5, 'molality from molarity', 'An aqueous solution of ethanol (46 g mol<sup>-1</sup>) is 4.80 M and has density 0.96 g mL<sup>-1</sup>. What is its molality? Give the answer to 2 decimals.', 6.49, 0.03, 'mol kg<sup>-1</sup>', '<p>Take 1 L: mass = 960 g. Ethanol = 4.80 × 46 = 220.8 g.</p><p>Water = 960 - 220.8 = 739.2 g = 0.7392 kg.</p><p>Molality = 4.80 / 0.7392 = <b>6.49 mol kg<sup>-1</sup></b>.</p><p>Molality is larger than molarity here because the solvent is only 0.739 kg, less than 1 kg, per litre of solution.</p>', 'm = M / (d - M × M<sub>solute</sub>/1000) with d in kg L<sup>-1</sup>.'),
    mk('mc-090', 5, 'mixed: gas laws and moles', 'A 2 L vessel contains 3.2 g of O<sub>2</sub> and 2.8 g of N<sub>2</sub> at 27 °C. Which expression gives the partial pressure of O<sub>2</sub> in atm? (R = 0.082 L atm K<sup>-1</sup> mol<sup>-1</sup>; O = 16, N = 14)', '0.1 × 0.082 × 300 / 2 = 1.23', ['0.2 × 0.082 × 300 / 2 = 2.46', '0.1 × 0.082 × 27 / 2 = 0.11', '(0.1 + 0.1) × 0.082 × 300 / 2 = 2.46'], '<p>Each gas obeys PV = nRT on its own.</p><p>n(O<sub>2</sub>) = 3.2 / 32 = 0.1 mol. (N<sub>2</sub> = 2.8 / 28 = 0.1 mol, but it is not needed.)</p><p>P(O<sub>2</sub>) = nRT / V = 0.1 × 0.082 × 300 / 2 = <b>1.23 atm</b>.</p><p>The other options use 27 K, double the moles or the total pressure.</p>', 'Use T in kelvin and only the moles of the gas in question.'),
    msq('mc-091', 5, 'limiting reagent', 'For 4NH<sub>3</sub> + 5O<sub>2</sub> → 4NO + 6H<sub>2</sub>O, 68 g of NH<sub>3</sub> reacts with 96 g of O<sub>2</sub>. (N = 14, H = 1, O = 16) Which statements are correct?', ['NH<sub>3</sub> is the limiting reagent', 'O<sub>2</sub> is the limiting reagent', 'At most 2.4 mol of NO can form', '1.6 mol of NH<sub>3</sub> remains unreacted'], [1, 2, 3], '<p>NH<sub>3</sub> = 68 / 17 = 4 mol. O<sub>2</sub> = 96 / 32 = 3 mol.</p><p>Divide by the coefficients: NH<sub>3</sub> 4/4 = 1.0; O<sub>2</sub> 3/5 = 0.6. The smaller is O<sub>2</sub>, so O<sub>2</sub> is limiting (B is correct, A is wrong).</p><p>NO formed = 3 × 4/5 = 2.4 mol (C is correct). NH<sub>3</sub> used = 2.4 mol, left = 4 - 2.4 = 1.6 mol (D is correct).</p><p>Answer: B, C and D.</p>', 'NH<sub>3</sub> has the larger mass and the larger mole count, yet it is the reagent in excess.'),
    // ---------- Passages ----------
    PN('mc-092', 3, 'combustion analysis', 'p1', 'What is the mass of oxygen in the sample, in grams? (Use the passage; C = 12, H = 1, O = 16)', 0.32, 0.005, 'g', '<p>C in CO<sub>2</sub>: 1.76 × 12/44 = 0.48 g. H in H<sub>2</sub>O: 1.08 × 2/18 = 0.12 g.</p><p>Oxygen is the rest: 0.92 - 0.48 - 0.12 = <b>0.32 g</b>.</p>', 'Oxygen is found by difference, because it is also taken from the air when burning.'),
    P('mc-093', 3, 'combustion analysis', 'p1', 'The empirical formula of the compound is', 'C<sub>2</sub>H<sub>6</sub>O', ['CH<sub>3</sub>O', 'C<sub>2</sub>H<sub>4</sub>O', 'C<sub>3</sub>H<sub>8</sub>O'], '<p>Moles: C = 0.48/12 = 0.04; H = 0.12/1 = 0.12; O = 0.32/16 = 0.02.</p><p>Divide by 0.02: C : H : O = 2 : 6 : 1. Empirical formula = <b>C<sub>2</sub>H<sub>6</sub>O</b>.</p>'),
    PN('mc-094', 4, 'combustion analysis', 'p1', 'How many moles of the compound are present in the 0.92 g sample?', 0.02, 0.001, 'mol', '<p>Molar mass = 2 × vapour density = 2 × 23 = 46 g mol<sup>-1</sup>. The empirical formula mass of C<sub>2</sub>H<sub>6</sub>O is also 24 + 6 + 16 = 46, so the molecular formula is C<sub>2</sub>H<sub>6</sub>O.</p><p>Moles = 0.92 / 46 = <b>0.02 mol</b>.</p>'),
    PN('mc-095', 3, 'concentration terms', 'p2', 'What is the molarity of ethanol in the solution, in M?', 4.8, 0.05, 'M', '<p>Take 100 g of solution: ethanol = 23 g = 0.5 mol; water = 77 g.</p><p>Volume = 100 / 0.96 = 104.2 mL = 0.1042 L.</p><p>M = 0.5 / 0.1042 = <b>4.8 M</b>.</p>'),
    PN('mc-096', 3, 'concentration terms', 'p2', 'What is the molality of ethanol in the solution, in mol kg<sup>-1</sup>?', 6.49, 0.03, 'mol kg<sup>-1</sup>', '<p>In 100 g of solution: ethanol 0.5 mol, water 77 g = 0.077 kg.</p><p>Molality = 0.5 / 0.077 = <b>6.49 mol kg<sup>-1</sup></b>.</p><p>The density is not needed for molality.</p>', 'Density matters for molarity, not for molality or mole fraction.'),
    PN('mc-097', 4, 'concentration terms', 'p2', 'What is the mole fraction of ethanol in the solution? Give the answer to 3 decimals.', 0.105, 0.002, '', '<p>Ethanol = 0.5 mol. Water = 77 / 18 = 4.278 mol.</p><p>x = 0.5 / (0.5 + 4.278) = 0.5 / 4.778 = <b>0.105</b>.</p>'),
    PN('mc-098', 4, 'mixture analysis', 'p3', 'How many millimoles of Na<sub>2</sub>CO<sub>3</sub> are in the sample?', 3, 0, 'mmol', '<p>At the phenolphthalein point only Na<sub>2</sub>CO<sub>3</sub> reacts (to NaHCO<sub>3</sub>), 1 : 1 with HCl.</p><p>HCl = 30.0 × 0.100 = 3.0 mmol, so Na<sub>2</sub>CO<sub>3</sub> = <b>3 mmol</b>.</p>', 'The original NaHCO<sub>3</sub> does not react with HCl at the first end point.'),
    PN('mc-099', 5, 'mixture analysis', 'p3', 'How many millimoles of NaHCO<sub>3</sub> were present in the original sample?', 2, 0, 'mmol', '<p>Total HCl to methyl orange = 80.0 × 0.100 = 8.0 mmol.</p><p>Na<sub>2</sub>CO<sub>3</sub> needs 2 HCl per mole in total (to CO<sub>2</sub>): 2 × 3 = 6 mmol. The rest is for the original NaHCO<sub>3</sub> (1 HCl each): 8 - 6 = 2 mmol.</p><p>Answer: <b>2 mmol</b>. (Another way: the second stage takes 50 mL = 5 mmol = 3 from the new NaHCO<sub>3</sub> + 2 original.)</p>', 'The NaHCO<sub>3</sub> formed from Na<sub>2</sub>CO<sub>3</sub> also reacts in the second stage.'),
    PN('mc-100', 5, 'mixture analysis', 'p3', 'What is the percentage by mass of NaHCO<sub>3</sub> in the sample? (Na = 23, H = 1, C = 12, O = 16) Give the answer to 1 decimal place.', 34.6, 0.2, '%', '<p>NaHCO<sub>3</sub> = 2 mmol × 84 = 168 mg. Na<sub>2</sub>CO<sub>3</sub> = 3 mmol × 106 = 318 mg. Total = 486 mg ✓ (matches 0.486 g).</p><p>% NaHCO<sub>3</sub> = 168 / 486 × 100 = <b>34.6%</b>.</p>'),
  ],
  gens: [
    { id: 'mc-g01', type: 'nat', level: 2, exams: EX[2], sub: 'mole and Avogadro number',
      make(rng) {
        const c = choose(rng, [['H<sub>2</sub>O', 18], ['CO<sub>2</sub>', 44], ['NH<sub>3</sub>', 17], ['CH<sub>4</sub>', 16], ['H<sub>2</sub>SO<sub>4</sub>', 98], ['NaCl', 58.5]]);
        const mol = pick(rng, 0.2, 3, 0.2); const mass = +(mol * c[1]).toFixed(2);
        const ans = +(mass / c[1] * 60.22).toFixed(3);
        return { q: `How many molecules are present in ${mass} g of ${c[0]}? Give the answer in units of 10<sup>22</sup> molecules (N<sub>A</sub> = 6.022 × 10<sup>23</sup>; molar mass ${c[1]} g mol<sup>-1</sup>).`, answer: ans, tol: +(ans * 0.01).toFixed(3), unit: '× 10<sup>22</sup>', mass, M: c[1],
          sol: `<p>Moles = mass / molar mass = ${mass} / ${c[1]} = ${fmt(mass / c[1], 4)} mol.</p><p>Molecules = moles × N<sub>A</sub> = ${fmt(mass / c[1], 4)} × 6.022 × 10<sup>23</sup> = ${fmt(ans, 4)} × 10<sup>22</sup>.</p>` };
      }, verify: (p) => p.mass / p.M * 6.022e23 / 1e22 },
    { id: 'mc-g02', type: 'nat', level: 2, exams: EX[2], sub: 'molarity',
      make(rng) {
        const s = choose(rng, [['NaOH', 40], ['Na<sub>2</sub>CO<sub>3</sub>', 106], ['KCl', 74.5], ['H<sub>2</sub>SO<sub>4</sub>', 98]]);
        const M = pick(rng, 0.1, 2, 0.1), V = choose(rng, [200, 250, 400, 500, 1000]);
        const mass = +(M * s[1] * V / 1000).toFixed(3);
        return { q: `${mass} g of ${s[0]} is dissolved in water to make ${V} mL of solution. What is the molarity? (Molar mass ${s[1]} g mol<sup>-1</sup>)`, answer: M, tol: +(M * 0.01 + 0.0005).toFixed(4), unit: 'M', mass, V, mm: s[1],
          sol: `<p>Moles = ${mass} / ${s[1]} = ${fmt(mass / s[1], 4)} mol.</p><p>Volume = ${V} mL = ${V / 1000} L.</p><p>M = ${fmt(mass / s[1], 4)} / ${V / 1000} = <b>${M} M</b>.</p>` };
      }, verify: (p) => (p.mass / p.mm) / (p.V / 1000) },
    { id: 'mc-g03', type: 'nat', level: 2, exams: EX[2], sub: 'dilution',
      make(rng) {
        const M1 = pick(rng, 1, 10, 1), V1 = pick(rng, 10, 100, 10), V2 = choose(rng, [250, 500, 1000]);
        const M2 = M1 * V1 / V2;
        return { q: `${V1} mL of ${M1} M HCl is diluted with water to a final volume of ${V2} mL. What is the molarity of the diluted acid?`, answer: +M2.toFixed(4), tol: +(M2 * 0.01 + 0.0005).toFixed(4), unit: 'M', M1, V1, V2,
          sol: `<p>Moles of HCl stay the same: M<sub>1</sub>V<sub>1</sub> = M<sub>2</sub>V<sub>2</sub>.</p><p>${M1} × ${V1} = M<sub>2</sub> × ${V2}, so M<sub>2</sub> = ${fmt(M2, 4)} M.</p>` };
      }, verify: (p) => (p.M1 * p.V1 / 1000) / (p.V2 / 1000) },
    { id: 'mc-g04', type: 'nat', level: 2, exams: EX[2], sub: 'mixing of solutions',
      make(rng) {
        const M1 = pick(rng, 0.2, 2, 0.2), V1 = pick(rng, 100, 500, 100), M2 = pick(rng, 0.2, 2, 0.2), V2 = pick(rng, 100, 500, 100);
        const M = (M1 * V1 + M2 * V2) / (V1 + V2);
        return { q: `${V1} mL of ${M1} M NaCl is mixed with ${V2} mL of ${M2} M NaCl. Assuming volumes add, what is the molarity of the mixture?`, answer: +M.toFixed(4), tol: +(M * 0.01 + 0.0005).toFixed(4), unit: 'M', M1, V1, M2, V2,
          sol: `<p>Total moles = (${M1} × ${V1} + ${M2} × ${V2}) / 1000 = ${fmt((M1 * V1 + M2 * V2) / 1000, 4)} mol.</p><p>Total volume = ${(V1 + V2) / 1000} L.</p><p>M = ${fmt((M1 * V1 + M2 * V2) / 1000, 4)} / ${(V1 + V2) / 1000} = ${fmt(M, 4)} M. (Not the simple average of ${M1} and ${M2}, unless the volumes are equal.)</p>` };
      }, verify: (p) => (p.M1 * p.V1 / 1000 + p.M2 * p.V2 / 1000) / ((p.V1 + p.V2) / 1000) },
    { id: 'mc-g05', type: 'nat', level: 2, exams: EX[2], sub: 'mole fraction',
      make(rng) {
        const l = choose(rng, [['ethanol', 46], ['methanol', 32], ['acetic acid', 60]]);
        const nA = int(rng, 1, 4), nB = int(rng, 2, 8);
        const mA = +(nA * l[1]).toFixed(1), mB = nB * 18;
        const x = nA / (nA + nB);
        return { q: `A solution contains ${mA} g of ${l[0]} (${l[1]} g mol<sup>-1</sup>) and ${mB} g of water (18 g mol<sup>-1</sup>). What is the mole fraction of ${l[0]}? Give 3 decimals.`, answer: +x.toFixed(3), tol: 0.002, mA, mB, mm: l[1],
          sol: `<p>Moles of ${l[0]} = ${mA} / ${l[1]} = ${nA}. Moles of water = ${mB} / 18 = ${nB}.</p><p>x = ${nA} / (${nA} + ${nB}) = ${fmt(x, 3)}.</p>` };
      }, verify: (p) => (p.mA / p.mm) / (p.mA / p.mm + p.mB / 18) },
    { id: 'mc-g06', type: 'nat', level: 2, exams: EX[2], sub: 'molality',
      make(rng) {
        const s = choose(rng, [['glucose', 180], ['urea', 60], ['NaCl', 58.5], ['sucrose', 342]]);
        const n = pick(rng, 0.1, 1.5, 0.1), w = choose(rng, [250, 400, 500, 800, 1000]);
        const mass = +(n * s[1]).toFixed(2); const m = n / (w / 1000);
        return { q: `${mass} g of ${s[0]} (${s[1]} g mol<sup>-1</sup>) is dissolved in ${w} g of water. What is the molality of the solution?`, answer: +m.toFixed(4), tol: +(m * 0.01 + 0.001).toFixed(4), unit: 'mol kg<sup>-1</sup>', mass, w, mm: s[1],
          sol: `<p>Moles = ${mass} / ${s[1]} = ${fmt(mass / s[1], 4)} mol. Solvent = ${w} g = ${w / 1000} kg.</p><p>Molality = ${fmt(mass / s[1], 4)} / ${w / 1000} = ${fmt(m, 4)} mol kg<sup>-1</sup>.</p>` };
      }, verify: (p) => (p.mass / p.mm) * 1000 / p.w },
    { id: 'mc-g07', type: 'mcq', level: 3, exams: EX[3], sub: 'limiting reagent',
      make(rng) {
        let a, b; do { a = pick(rng, 0.5, 3, 0.5); b = pick(rng, 1, 8, 0.5); } while (Math.abs(b / 3 - a) < 0.1);
        const lim = Math.min(a, b / 3), ans = 2 * lim * 17;
        const wrongs = [2 * Math.max(a, b / 3) * 17, lim * 17, 2 * lim * 14, (a + b) * 17 / 2];
        const o = numOpts(rng, ans, wrongs, 'g', 3);
        const who = a < b / 3 ? 'N<sub>2</sub>' : 'H<sub>2</sub>';
        return { q: `${a} mol of N<sub>2</sub> and ${b} mol of H<sub>2</sub> react: N<sub>2</sub> + 3H<sub>2</sub> → 2NH<sub>3</sub>. What mass of NH<sub>3</sub> can form at most? (N = 14, H = 1)`, options: o.options, answer: o.answer, a, b,
          sol: `<p>Compare moles / coefficient: N<sub>2</sub> = ${a}/1 = ${a}; H<sub>2</sub> = ${b}/3 = ${fmt(b / 3, 3)}.</p><p>The smaller is ${who}, so ${who} is limiting.</p><p>NH<sub>3</sub> = 2 × ${fmt(lim, 3)} = ${fmt(2 * lim, 3)} mol. Mass = ${fmt(2 * lim, 3)} × 17 = <b>${fmt(ans, 3)} g</b>.</p>`, trap: 'Using the reagent present in excess gives a bigger, impossible answer.' };
      }, verify: (p) => p.options.indexOf(`${fmt(17 * Math.min(2 * p.a, 2 * p.b / 3), 3)} g`) },
    { id: 'mc-g08', type: 'nat', level: 2, exams: EX[2], sub: 'percentage yield',
      make(rng) {
        const k = choose(rng, [0.5, 1, 2, 2.5, 5]), y = choose(rng, [60, 65, 70, 75, 80, 85, 90]);
        const m = 100 * k, th = 56 * k, act = +(th * y / 100).toFixed(2);
        return { q: `${m} g of CaCO<sub>3</sub> is heated: CaCO<sub>3</sub> → CaO + CO<sub>2</sub>. The CaO collected weighs ${act} g. What is the percentage yield of CaO? (Ca = 40, C = 12, O = 16)`, answer: y, tol: 0.2, unit: '%', m, act,
          sol: `<p>${m} g CaCO<sub>3</sub> = ${k} mol, which can give ${k} mol CaO = ${th} g (theoretical).</p><p>Percentage yield = ${act} / ${th} × 100 = <b>${y}%</b>.</p>` };
      }, verify: (p) => p.act / (56 * p.m / 100) * 100 },
    { id: 'mc-g09', type: 'mcq', level: 2, exams: EX[2], sub: 'empirical formula',
      make(rng) {
        const fam = choose(rng, [['Fe', 56, [[1, 1], [2, 3], [3, 4]]], ['Cu', 63.5, [[1, 1], [2, 1]]], ['Ca', 40, [[1, 1], [1, 2]]]]);
        const all = [[1, 1], [2, 3], [3, 4], [1, 2], [2, 1]];
        const [sym, mm, good] = fam; const c = choose(rng, good);
        const f = ([a, b]) => `${sym}${a > 1 ? `<sub>${a}</sub>` : ''}O${b > 1 ? `<sub>${b}</sub>` : ''}`;
        const pct = +((c[0] * mm) / (c[0] * mm + 16 * c[1]) * 100).toFixed(1);
        const others = all.filter((r) => r[0] / r[1] !== c[0] / c[1]);
        const o = shuffleOpts(rng, f(c), others.slice(0, 3).map(f));
        const cands = o.options.map((t) => all.find((r) => f(r) === t));
        return { q: `An oxide of ${sym} contains ${pct}% ${sym} by mass. What is its empirical formula? (${sym} = ${mm}, O = 16)`, options: o.options, answer: o.answer, cands, mm, pct,
          sol: `<p>Take 100 g. Moles of ${sym} = ${pct} / ${mm} = ${fmt(pct / mm, 4)}. Moles of O = ${fmt(100 - pct, 4)} / 16 = ${fmt((100 - pct) / 16, 4)}.</p><p>Ratio ${sym} : O = ${fmt(pct / mm / ((100 - pct) / 16), 3)} : 1, which is ${c[0]} : ${c[1]}.</p><p>Empirical formula = <b>${f(c)}</b>.</p>` };
      }, verify: (p) => { const r = (p.pct / p.mm) / ((100 - p.pct) / 16); let best = 0, d = 9; p.cands.forEach((c, i) => { const e = Math.abs(c[0] / c[1] - r); if (e < d) { d = e; best = i; } }); return best; } },
    { id: 'mc-g10', type: 'nat', level: 3, exams: EX[3], sub: 'concentration terms',
      make(rng) {
        const r = choose(rng, [['HCl', 36.5, 36, 1.18], ['HCl', 36.5, 32, 1.16], ['HNO<sub>3</sub>', 63, 70, 1.42], ['HNO<sub>3</sub>', 63, 65, 1.39], ['H<sub>2</sub>SO<sub>4</sub>', 98, 98, 1.84], ['H<sub>2</sub>SO<sub>4</sub>', 98, 60, 1.5]]);
        const M = 10 * r[2] * r[3] / r[1];
        return { q: `A commercial ${r[0]} solution is ${r[2]}% by mass and has density ${r[3]} g mL<sup>-1</sup>. What is its molarity? (Molar mass ${r[1]} g mol<sup>-1</sup>)`, answer: +M.toFixed(3), tol: +(M * 0.01).toFixed(3), unit: 'M', w: r[2], d: r[3], mm: r[1],
          sol: `<p>1 L of solution = 1000 × ${r[3]} = ${fmt(1000 * r[3], 4)} g.</p><p>Solute = ${r[2]}% of that = ${fmt(10 * r[2] * r[3], 4)} g = ${fmt(10 * r[2] * r[3] / r[1], 4)} mol.</p><p>Molarity = <b>${fmt(M, 4)} M</b>.</p>` };
      }, verify: (p) => (1000 * p.d * p.w / 100) / p.mm },
    { id: 'mc-g11', type: 'nat', level: 3, exams: EX[3], sub: 'redox titration',
      make(rng) {
        const M1 = choose(rng, [0.02, 0.04, 0.05]), V1 = choose(rng, [10, 20, 25, 30, 40]);
        const sp = choose(rng, [['Fe<sup>2+</sup> solution', 1, 'Fe<sup>2+</sup> to Fe<sup>3+</sup>'], ['oxalic acid solution', 2, 'C<sub>2</sub>O<sub>4</sub><sup>2-</sup> to CO<sub>2</sub>']]);
        const M2 = choose(rng, [0.1, 0.25, 0.5]);
        const V2 = 5 * M1 * V1 / (sp[1] * M2);
        return { q: `${V1} mL of ${M1} M KMnO<sub>4</sub> (acidic medium) is just enough to oxidise ${M2} M ${sp[0]} (${sp[2]}). What volume of the ${sp[0]} is needed, in mL?`, answer: +V2.toFixed(3), tol: +(V2 * 0.01 + 0.02).toFixed(3), unit: 'mL', M1, V1, M2, n: sp[1],
          sol: `<p>KMnO<sub>4</sub> n-factor = 5, so its normality = ${M1} × 5 = ${fmt(M1 * 5, 3)} N. The other n-factor = ${sp[1]}, normality = ${fmt(M2 * sp[1], 3)} N.</p><p>N<sub>1</sub>V<sub>1</sub> = N<sub>2</sub>V<sub>2</sub>: ${fmt(M1 * 5, 3)} × ${V1} = ${fmt(M2 * sp[1], 3)} × V<sub>2</sub>.</p><p>V<sub>2</sub> = <b>${fmt(V2, 4)} mL</b>.</p>` };
      }, verify: (p) => (p.M1 * 5 * p.V1) / (p.M2 * p.n) },
    { id: 'mc-g12', type: 'nat', level: 3, exams: EX[3], sub: 'eudiometry',
      make(rng) {
        const h = choose(rng, [['CH<sub>4</sub>', 1, 4], ['C<sub>2</sub>H<sub>6</sub>', 2, 6], ['C<sub>2</sub>H<sub>4</sub>', 2, 4], ['C<sub>2</sub>H<sub>2</sub>', 2, 2], ['C<sub>3</sub>H<sub>8</sub>', 3, 8], ['C<sub>3</sub>H<sub>6</sub>', 3, 6]]);
        const V = choose(rng, [10, 20, 30, 40]); const o2 = V * (h[1] + h[2] / 4); const cont = V * (1 + h[2] / 4);
        return { q: `${V} mL of ${h[0]} is burnt completely in excess oxygen. After cooling to room temperature (water is liquid), what is the contraction in volume, in mL?`, answer: cont, tol: 0.01, unit: 'mL', V, x: h[1], y: h[2],
          sol: `<p>C<sub>${h[1]}</sub>H<sub>${h[2]}</sub> + (${h[1]} + ${h[2]}/4) O<sub>2</sub> → ${h[1]} CO<sub>2</sub> + ${h[2] / 2} H<sub>2</sub>O(l).</p><p>Gas used: ${V} + ${fmt(o2, 4)} = ${fmt(V + o2, 4)} mL. Gas formed: ${V * h[1]} mL CO<sub>2</sub>.</p><p>Contraction = ${fmt(V + o2, 4)} - ${V * h[1]} = <b>${fmt(cont, 4)} mL</b>.</p>` };
      }, verify: (p) => (p.V + p.V * (p.x + p.y / 4)) - p.V * p.x },
    { id: 'mc-g13', type: 'nat', level: 3, exams: EX[3], sub: 'hydrated salts',
      make(rng) {
        const x = int(rng, 1, 7), pct = +(100 * 18 * x / (120 + 18 * x)).toFixed(1);
        return { q: `A sample of MgSO<sub>4</sub>·xH<sub>2</sub>O loses ${pct}% of its mass on heating to the anhydrous salt. Find x. (Mg = 24, S = 32, O = 16, H = 1)`, answer: x, tol: 0.1, pct,
          sol: `<p>Anhydrous MgSO<sub>4</sub> = 24 + 32 + 64 = 120. Water per mole of hydrate = 18x.</p><p>18x / (120 + 18x) = ${pct / 100}. So 18x = ${pct / 100} × 120 + ${pct / 100} × 18x, giving 18x (1 - ${pct / 100}) = ${fmt(pct * 1.2, 4)}.</p><p>x = <b>${x}</b> (to the nearest whole number).</p>` };
      }, verify: (p) => (p.pct * 120) / (18 * (100 - p.pct)) },
    { id: 'mc-g14', type: 'nat', level: 3, exams: EX[3], sub: 'stoichiometry',
      make(rng) {
        const m = choose(rng, [5, 10, 15, 20, 25, 50]), pur = choose(rng, [80, 90, 95, 100]);
        const V = m * pur / 100 / 100 * 22.4;
        return { q: `${m} g of limestone containing ${pur}% CaCO<sub>3</sub> is treated with excess HCl: CaCO<sub>3</sub> + 2HCl → CaCl<sub>2</sub> + H<sub>2</sub>O + CO<sub>2</sub>. What volume of CO<sub>2</sub> is produced at 273 K and 1 atm, in litres? (Ca = 40, C = 12, O = 16)`, answer: +V.toFixed(3), tol: +(V * 0.01 + 0.005).toFixed(3), unit: 'L', m, pur,
          sol: `<p>Pure CaCO<sub>3</sub> = ${m} × ${pur}/100 = ${fmt(m * pur / 100, 4)} g = ${fmt(m * pur / 10000, 4)} mol.</p><p>1 mol CaCO<sub>3</sub> gives 1 mol CO<sub>2</sub>, so CO<sub>2</sub> = ${fmt(m * pur / 10000, 4)} mol.</p><p>Volume = ${fmt(m * pur / 10000, 4)} × 22.4 = <b>${fmt(V, 4)} L</b>.</p>` };
      }, verify: (p) => (p.m * p.pur / 100 * 44 / 100) / 44 * 22.4 },
    { id: 'mc-g15', type: 'nat', level: 3, exams: EX[3], sub: 'atomic mass',
      make(rng) {
        const e = choose(rng, [['chlorine', 35, 37], ['copper', 63, 65], ['bromine', 79, 81], ['boron', 10, 11]]);
        const x = choose(rng, [20, 25, 30, 40, 60, 75]); const avg = +((e[1] * x + e[2] * (100 - x)) / 100).toFixed(3);
        return { q: `${e[0][0].toUpperCase() + e[0].slice(1)} has two isotopes of mass ${e[1]} u and ${e[2]} u. Its average atomic mass is ${avg} u. What is the percentage abundance of the lighter isotope?`, answer: x, tol: 0.1, unit: '%', a: e[1], b: e[2], avg,
          sol: `<p>Let the lighter isotope be x%. Then ${e[1]}x/100 + ${e[2]}(100 - x)/100 = ${avg}.</p><p>${e[2]} - (${e[2] - e[1]})x/100 = ${avg}, so x = (${e[2]} - ${avg}) × 100 / ${e[2] - e[1]} = <b>${x}%</b>.</p>` };
      }, verify: (p) => (p.b - p.avg) / (p.b - p.a) * 100 },
    { id: 'mc-g16', type: 'nat', level: 3, exams: EX[3], sub: 'concentration terms',
      make(rng) {
        const s = choose(rng, [['Ca<sup>2+</sup>', 40], ['Mg<sup>2+</sup>', 24], ['Na<sup>+</sup>', 23], ['Cl<sup>-</sup>', 35.5]]);
        const ppm = choose(rng, [20, 40, 60, 80, 120, 200, 355]);
        const mM = ppm / s[1];
        return { q: `A water sample has ${ppm} ppm of ${s[0]} by mass. Take the density as 1 g mL<sup>-1</sup>. What is the concentration of ${s[0]} in mmol per litre? (Atomic mass ${s[1]})`, answer: +mM.toFixed(4), tol: +(mM * 0.01 + 0.001).toFixed(4), unit: 'mmol L<sup>-1</sup>', ppm, mm: s[1],
          sol: `<p>${ppm} ppm = ${ppm} mg per kg of solution. With 1 g mL<sup>-1</sup>, that is ${ppm} mg per litre.</p><p>Moles = ${ppm} mg / ${s[1]} g mol<sup>-1</sup> = <b>${fmt(mM, 4)} mmol per litre</b>.</p>` };
      }, verify: (p) => p.ppm / p.mm },
    { id: 'mc-g17', type: 'nat', level: 4, exams: EX[4], sub: 'mixing of solutions',
      make(rng) {
        let Ma, Va, Mb, Vb; do { Ma = pick(rng, 0.1, 1, 0.1); Va = pick(rng, 100, 400, 50); Mb = pick(rng, 0.1, 1, 0.1); Vb = pick(rng, 100, 400, 50); } while (Math.abs(Ma * Va - Mb * Vb) < 1);
        const net = Math.abs(Ma * Va - Mb * Vb) / (Va + Vb); const who = Ma * Va > Mb * Vb ? 'H<sup>+</sup>' : 'OH<sup>-</sup>';
        return { q: `${Va} mL of ${Ma} M HCl is mixed with ${Vb} mL of ${Mb} M NaOH. What is the molarity of the excess ion (H<sup>+</sup> or OH<sup>-</sup>) in the final solution?`, answer: +net.toFixed(4), tol: +(net * 0.01 + 0.0005).toFixed(4), unit: 'M', Ma, Va, Mb, Vb,
          sol: `<p>Millimoles H<sup>+</sup> = ${Ma} × ${Va} = ${fmt(Ma * Va, 4)}. Millimoles OH<sup>-</sup> = ${Mb} × ${Vb} = ${fmt(Mb * Vb, 4)}.</p><p>They cancel 1 : 1, leaving ${fmt(Math.abs(Ma * Va - Mb * Vb), 4)} mmol of ${who}.</p><p>Total volume = ${Va + Vb} mL. Molarity = ${fmt(Math.abs(Ma * Va - Mb * Vb), 4)} / ${Va + Vb} = <b>${fmt(net, 4)} M</b>.</p>` };
      }, verify: (p) => Math.abs(p.Ma * p.Va - p.Mb * p.Vb) / (p.Va + p.Vb) },
  ],
};
